# Test without importing astropy (to avoid the config error)
import sys
sys.modules['astropy'] = type(sys)('astropy')

import inspect
# Copy the class directly
import abc

class InheritDocstrings(type):
    def __init__(cls, name, bases, dct):
        def is_public_member(key):
            return (
                (key.startswith('__') and key.endswith('__')
                 and len(key) > 4) or
                not key.startswith('_'))

        for key, val in dct.items():
            if (inspect.isfunction(val) and
                is_public_member(key) and
                val.__doc__ is None):
                for base in cls.__mro__[1:]:
                    super_method = getattr(base, key, None)
                    if super_method is not None:
                        val.__doc__ = super_method.__doc__
                        break
            elif (isinstance(val, property) and
                  is_public_member(key) and
                  val.fget is not None and
                  val.fget.__doc__ is None):
                for base in cls.__mro__[1:]:
                    super_property = getattr(base, key, None)
                    if super_property is not None:
                        val.__doc__ = super_property.__doc__
                        break

        super().__init__(name, bases, dct)

# Test 1: Basic property inheritance
class A(metaclass=InheritDocstrings):
    @property
    def prop(self):
        'Property docstring'
        return 1

class B(A):
    @property
    def prop(self):
        return 2

print('Test 1 - Basic property:', repr(B.prop.__doc__))
assert B.prop.__doc__ == 'Property docstring', f'Failed: {B.prop.__doc__!r}'

# Test 2: Property with explicit doc shouldn't be overridden
class C(A):
    @property
    def prop(self):
        'Explicit docstring'
        return 3

print('Test 2 - Explicit doc:', repr(C.prop.__doc__))
assert C.prop.__doc__ == 'Explicit docstring', f'Failed: {C.prop.__doc__!r}'

# Test 3: Regular method still works
class D(metaclass=InheritDocstrings):
    def method(self):
        'Method docstring'
        pass

class E(D):
    def method(self):
        pass

print('Test 3 - Regular method:', repr(E.method.__doc__))
assert E.method.__doc__ == 'Method docstring'

# Test 4: Private property should not inherit
class F(metaclass=InheritDocstrings):
    @property
    def _private(self):
        'Private docstring'
        return 1

class G(F):
    @property
    def _private(self):
        return 2

print('Test 4 - Private property:', repr(G._private.__doc__))
assert G._private.__doc__ is None

print('All tests passed!')
"

